<?php require __DIR__.'/includes/config.php';require_login();$id=(int)($_GET['id']??0);$q=$pdo->prepare('SELECT * FROM installations WHERE id=? LIMIT 1');$q->execute([$id]);$s=$q->fetch();if(!$s||($_SESSION['user']['role']!=='ADMIN'&&(int)$s['provider_id']!==(int)$_SESSION['user']['id'])){http_response_code(404);exit('Mission introuvable.');}$photos=json_decode($s['photos_json']??'[]',true)?:[];$m=json_decode($s['measurements_json']??'{}',true)?:[];$error='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();if(isset($_POST['save_measurements'])){$keys=['face_h','face_l','fronton_h','fronton_l','plinthe_h','plinthe_l','cotes_h','cotes_l_haut','cotes_l_bas'];$data=[];foreach($keys as $k){$v=trim((string)($_POST[$k]??''));if($v!==''&&(!is_numeric($v)||(float)$v<0||(float)$v>10000)){$error='Mesure invalide.';break;}$data[$k]=$v===''?null:(float)$v;}if(!$error){$q=$pdo->prepare('UPDATE installations SET measurements_json=?,status=IF(status="A_REPERER","MESURES_PRISES",status),updated_at=NOW() WHERE id=?');$q->execute([json_encode($data,JSON_UNESCAPED_UNICODE),$id]);header('Location: store.php?id='.$id.'&saved=1');exit;}}if(isset($_POST['upload_photos'])){$files=$_FILES['photos']??null;$count=$files?count(array_filter($files['name'],fn($n)=>$n!=='')):0;if(!$files||$count<1)$error='Choisissez des photos.';elseif(count($photos)+$count>5)$error='Maximum 5 photos par magasin.';else{$dir=__DIR__.'/uploads/photos';if(!is_dir($dir))mkdir($dir,0750,true);for($i=0;$i<count($files['name']);$i++){if($files['error'][$i]===UPLOAD_ERR_NO_FILE)continue;if($files['error'][$i]!==UPLOAD_ERR_OK||$files['size'][$i]>10*1024*1024){$error='Photo invalide (10 Mo max).';break;}$mime=(new finfo(FILEINFO_MIME_TYPE))->file($files['tmp_name'][$i]);$ext=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'][$mime]??null;if(!$ext||!is_uploaded_file($files['tmp_name'][$i])){$error='Format autorisé : JPG, PNG ou WebP.';break;}$name=bin2hex(random_bytes(16)).'.'.$ext;if(!move_uploaded_file($files['tmp_name'][$i],$dir.'/'.$name)){$error='Échec de l’enregistrement.';break;}$photos[]='uploads/photos/'.$name;}if(!$error){$q=$pdo->prepare('UPDATE installations SET photos_json=?,updated_at=NOW() WHERE id=?');$q->execute([json_encode($photos),$id]);header('Location: store.php?id='.$id.'&uploaded=1');exit;}}}$pageTitle=$s['store_name'];require __DIR__.'/includes/header.php';?><a href="<?=($_SESSION['user']['role']==='ADMIN'?'admin.php':'stores.php')?>" class="text-sm brand font-semibold">← Retour</a><div class="mt-4 flex flex-wrap justify-between gap-3"><div><span class="text-xs uppercase tracking-widest gold font-bold"><?=e($s['banner'])?> · <?=e($s['city'])?></span><h1 class="text-3xl font-extrabold mt-2"><?=e($s['store_name'])?></h1><p class="text-stone-500 mt-1">Statut : <?=e(status_label($s['status']))?></p></div><?php if($s['tech_sheet_url']):?><a class="btn self-start" href="<?=e($s['tech_sheet_url'])?>" target="_blank" rel="noopener">Ouvrir la fiche technique ↗</a><?php endif;?></div><?php if(isset($_GET['saved'])||isset($_GET['uploaded'])):?><p class="mt-4 bg-green-50 text-green-800 rounded-xl p-3">Enregistré avec succès.</p><?php endif;?><?php if($error):?><p class="mt-4 bg-red-50 text-red-800 rounded-xl p-3"><?=e($error)?></p><?php endif;?><div class="grid lg:grid-cols-2 gap-5 mt-6"><section class="card p-5"><h2 class="text-xl font-bold">Relevé des mesures</h2><p class="text-sm text-stone-500 mt-1 mb-4">Dimensions en centimètres.</p><form method="post" class="space-y-4"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="save_measurements" value="1"><?php $groups=['Face'=>['face_h'=>'Hauteur','face_l'=>'Largeur'],'Fronton'=>['fronton_h'=>'Hauteur','fronton_l'=>'Largeur'],'Plinthe'=>['plinthe_h'=>'Hauteur','plinthe_l'=>'Largeur'],'Côtés'=>['cotes_h'=>'Hauteur globale','cotes_l_haut'=>'Largeur haut','cotes_l_bas'=>'Largeur bas']];foreach($groups as $g=>$fields):?><div><h3 class="font-semibold brand mb-2"><?=e($g)?></h3><div class="grid grid-cols-2 gap-3"><?php foreach($fields as $k=>$label):?><label class="text-sm text-stone-600"><?=e($label)?><input type="number" min="0" max="10000" step="0.1" name="<?=e($k)?>" value="<?=e((string)($m[$k]??''))?>" class="mt-1 w-full rounded-lg border border-stone-300 p-2.5" placeholder="cm"></label><?php endforeach;?></div></div><?php endforeach;?><button class="btn w-full">Enregistrer les mesures</button></form></section><section class="card p-5"><h2 class="text-xl font-bold">Photos terrain</h2><p class="text-sm text-stone-500 mt-1 mb-4">JPG, PNG ou WebP · 10 Mo max. · 5 photos au total.</p><form method="post" enctype="multipart/form-data" class="space-y-4"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="upload_photos" value="1"><input type="file" name="photos[]" multiple accept="image/jpeg,image/png,image/webp" class="block w-full text-sm"><button class="btn w-full">Téléverser les photos</button></form><div class="mt-5 grid grid-cols-2 gap-3"><?php foreach($photos as $p):?><a target="_blank" rel="noopener" href="<?=e($p)?>"><img src="<?=e($p)?>" alt="Photo d’installation" class="w-full h-36 object-cover rounded-lg border"></a><?php endforeach;?></div><p class="text-xs text-stone-500 mt-3"><?=count($photos)?> photo(s) enregistrée(s).</p></section></div><?php require __DIR__.'/includes/footer.php'; ?>